from fastmcp import FastMCP, Context
from fastmcp.types import Tool
import httpx


def create_openapi_mcp_server(
    openapi_spec: dict[str, Any],
    client: httpx.AsyncClient,
    server_name: str = "openapi-server",
) -> FastMCP:
    """
    Generate an MCP server from an OpenAPI 3.0 spec with tools mirroring the operations.

    Args:
        openapi_spec: OpenAPI 3.0 specification as a Python dict
        client: httpx.AsyncClient configured with the API base URL
        server_name: Name for the MCP server

    Returns:
        FastMCP server instance ready to use
    """
    mcp = FastMCP(server_name)

    # Extract paths from the spec
    paths = openapi_spec.get("paths", {})

    for path_str, path_item in paths.items():
        for method, operation in path_item.items():
            if method.lower() not in ["get", "post", "put", "patch", "delete", "head", "options"]:
                continue

            operation_id = operation.get("operationId", f"{method}_{path_str.replace('/', '_')}")
            summary = operation.get("summary", f"{method.upper()} {path_str}")
            description = operation.get("description", "")

            # Extract parameters
            parameters = operation.get("parameters", [])
            request_body = operation.get("requestBody", {})

            # Build the tool schema
            properties = {}
            required_fields = []

            # Add path and query parameters
            for param in parameters:
                param_name = param.get("name", "")
                param_in = param.get("in", "")
                param_schema = param.get("schema", {})

                properties[param_name] = {
                    "type": param_schema.get("type", "string"),
                    "description": param.get("description", f"{param_in} parameter"),
                }

                if param.get("required", False):
                    required_fields.append(param_name)

            # Add request body if present
            if request_body:
                content = request_body.get("content", {})
                if "application/json" in content:
                    body_schema = content["application/json"].get("schema", {})
                    properties["body"] = {
                        "type": "object",
                        "description": "Request body",
                        "properties": body_schema.get("properties", {}),
                    }
                    if request_body.get("required", False):
                        required_fields.append("body")

            # Create tool handler function
            async def tool_handler(
                context: Context,
                operation_method: str = method,
                operation_path: str = path_str,
                operation_params: list = parameters,
                has_body: bool = bool(request_body),
                **kwargs: Any,
            ) -> dict[str, Any]:
                """Execute the OpenAPI operation."""
                url = operation_path
                query_params = {}
                headers = {}
                body_data = None

                for param in operation_params:
                    param_name = param.get("name", "")
                    param_in = param.get("in", "")

                    if param_name in kwargs:
                        value = kwargs[param_name]

                        if param_in == "query":
                            query_params[param_name] = value
                        elif param_in == "header":
                            headers[param_name] = value
                        elif param_in == "path":
                            url = url.replace(f"{{{param_name}}}", str(value))

                if has_body and "body" in kwargs:
                    body_data = kwargs["body"]

                # Make the request
                try:
                    response = await client.request(
                        operation_method.upper(),
                        url,
                        params=query_params,
                        headers=headers,
                        json=body_data if isinstance(body_data, dict) else None,
                        content=body_data if isinstance(body_data, str) else None,
                    )

                    result = {
                        "status_code": response.status_code,
                        "headers": dict(response.headers),
                    }

                    try:
                        result["body"] = response.json()
                    except Exception:
                        result["body"] = response.text

                    return result
                except Exception as e:
                    return {"error": str(e)}

            # Register the tool with FastMCP
            tool_schema = {
                "type": "object",
                "properties": properties,
                "required": required_fields,
            }

            mcp.tool(
                name=operation_id,
                description=summary + (f"\n{description}" if description else ""),
            )(tool_handler)

    return mcp


